FILES = [('app/llm/reliable_extraction.py', '118a0cba7a2a91425fe52ba003039c06575f915c7b7cdf71839a9a9f1c240554', '"""Bounded structured extraction with private raw evidence and validated checkpoints."""\nimport hashlib\nimport json\nimport os\nimport tempfile\nfrom contextvars import ContextVar\nfrom pathlib import Path\nfrom pydantic import ValidationError\n\nVERSION = \'llm-reliable-20261019-v1\'\n_context = ContextVar(\'extraction_evidence\', default=None)\n\ndef digest(value):\n    return hashlib.sha256(value.encode()).hexdigest()\n\ndef write(path, value):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    fd, tmp = tempfile.mkstemp(dir=path.parent)\n    try:\n        with os.fdopen(fd, \'w\', encoding=\'utf-8\') as f:\n            json.dump(value, f, ensure_ascii=False, default=str)\n        os.replace(tmp, path)\n    finally:\n        if os.path.exists(tmp): os.unlink(tmp)\n\ndef finish_reason(response):\n    raw = response.raw\n    if isinstance(raw, dict):\n        alternatives = (raw.get(\'result\') or {}).get(\'alternatives\') or []\n        return alternatives[0].get(\'status\') if alternatives else None\n    return getattr(raw, \'stop_reason\', None)\n\nasync def extract_chunk(text, ns):\n    text = ns[\'_complete_document_text\'](text)\n    model = ns[\'TenderMultiExtractionResult\']\n    schema = json.dumps(model.model_json_schema(), ensure_ascii=False)\n    base = (\n        \'Извлеки только фактические строки спецификации. Общие условия, заголовок, \'\n        \'пустые формы: positions=[]. Номера лотов и позиций только из источника. \'\n        \'Не объединяй разные изделия и размеры в одну позицию. value — скаляр \'\n        \'или null; raw_quote — точная короткая цитата строкой или null. \'\n        \'Не распределяй общий объём по размерам самостоятельно. Альтернативные \'\n        \'размеры одной позиции: value=null, требование в raw_quote. \'\n        \'Не повторяй общий текст договора в каждой позиции.\\nСхема:\\n\' + schema\n        + \'\\nИсходный фрагмент:\\n\' + text\n    )\n    prompt = base\n    for attempt in range(2):\n        response = await ns[\'llm_router\'].complete(\n            task=ns[\'TaskType\'].EXTRACT_FIELDS,\n            system_prompt=ns[\'MULTI_EXTRACTION_SYSTEM_PROMPT\'],\n            user_prompt=prompt, max_tokens=6000, temperature=0.0, json_mode=True,\n        )\n        reason = finish_reason(response)\n        context = _context.get()\n        evidence = {\n            \'provider\': response.provider, \'model\': response.model,\n            \'finish_reason\': reason, \'attempt\': attempt + 1,\n            \'text\': response.text,\n        }\n        # Persist before decoding; do not persist provider headers or credentials.\n        if context:\n            run, index = context\n            evidence_path = run / f\'chunk-{index:04d}-attempt-{attempt+1}.json\'\n            write(evidence_path, evidence)\n        try:\n            if reason in {\'max_tokens\', \'ALTERNATIVE_STATUS_TRUNCATED\'}:\n                raise ValueError(\'LLM_RESPONSE_TRUNCATED\')\n            result = model.model_validate(response.as_json())\n        except (ValueError, ValidationError) as exc:\n            if context:\n                evidence[\'error_type\'] = type(exc).__name__\n                evidence[\'error\'] = str(exc)\n                write(evidence_path, evidence)\n            if attempt:\n                raise ValueError(\'EXTRACTION_RESPONSE_INVALID_AFTER_RETRY: \' + str(exc)) from exc\n            if isinstance(exc, ValidationError):\n                issues = [{\'path\': list(e[\'loc\']), \'type\': e[\'type\']}\n                          for e in exc.errors(include_input=False, include_url=False)]\n                hint = json.dumps(issues, ensure_ascii=False)\n            else:\n                hint = \'Невалидный или незавершённый JSON. Проверь кавычки и запятые.\'\n            prompt = base + \'\\nПовторная попытка: \' + hint + (\n                \'\\nИзвлеки заново из источника. Верни компактный полный JSON, \'\n                \'короткие цитаты. Не добавляй объяснения. Не теряй строки спецификации.\'\n            )\n        else:\n            return result\n\nasync def extract_all(text, ns):\n    from app.core.config import settings\n    chunks = ns[\'_document_chunks\'](text, limit=8000)\n    root = Path(settings.storage_path) / \'extraction_snapshots\'\n    root.mkdir(parents=True, exist_ok=True)\n    run = Path(tempfile.mkdtemp(prefix=digest(text)[:16]+\'-\', dir=root))\n    route = ns[\'llm_router\']._resolve_route(ns[\'TaskType\'].EXTRACT_FIELDS)\n    # Invalidate checkpoints for changed model, schema, prompts or extraction code.\n    fingerprint = digest(json.dumps({\n        \'version\': VERSION, \'input\': digest(text), \'route\': route,\n        \'schema\': ns[\'TenderMultiExtractionResult\'].model_json_schema(),\n        \'prompt\': ns[\'MULTI_EXTRACTION_SYSTEM_PROMPT\'],\n        \'code\': digest(Path(ns[\'__file__\']).read_text()),\n    }, sort_keys=True, ensure_ascii=False))\n    cache = root / \'_validated_cache\' / fingerprint\n    state = {\'input_sha256\': digest(text), \'version\': VERSION,\n             \'chunk_count\': len(chunks), \'state\': \'running\', \'responses\': []}\n    path = run / \'responses.json\'\n    write(path, state)\n    results = []\n    try:\n        for index, chunk in enumerate(chunks):\n            key = cache / (str(index) + \'-\' + digest(chunk) + \'.json\')\n            result = None\n            if key.exists():\n                try:\n                    result = ns[\'TenderMultiExtractionResult\'].model_validate(\n                        json.loads(key.read_text(encoding=\'utf-8\')))\n                except (ValueError, OSError):\n                    result = None\n            cached = result is not None\n            if not cached:\n                token = _context.set((run, index))\n                try:\n                    result = await extract_chunk(chunk, ns)\n                finally:\n                    _context.reset(token)\n                write(key, result.model_dump(mode=\'json\'))\n            state[\'responses\'].append({\'chunk_index\': index, \'chunk_sha256\': digest(chunk),\n                                      \'cached\': cached, \'result\': result.model_dump(mode=\'json\')})\n            write(path, state)\n            results.append(ns[\'_normalize_extraction\'](result, text))\n        from app.llm.gpb_position_reconcile import reconcile\n        results, mapping = reconcile(results, text)\n        state[\'source_position_mapping\'] = mapping\n        write(path, state)\n        merged = ns[\'_merge_extractions\'](results)\n        state[\'state\'] = \'completed\'\n        write(path, state)\n        return merged\n    except Exception as exc:\n        state.update(state=\'failed\', error_type=type(exc).__name__, error=str(exc))\n        write(path, state)\n        raise\n'), ('app/llm/gpb_position_reconcile.py', None, '"""Reconcile GPB profile repeats using unique source rows, never total quantities."""\nimport json\nimport re\nfrom decimal import Decimal\n\nVERSION=\'gpb-profile-evidence-20261019-v1\'\n\ndef norm(value):\n    return re.sub(r\'\\s+\', \' \', str(value or \'\')).strip().casefold()\n\ndef profile_key(value):\n    # Restrict to an explicit aluminium-profile designation, not generic headings.\n    match=re.search(r\'профиль\\s+алюминиевый\\s+(\\d+(?:[.,]\\d+)?)\\s*[хx×]\\s*(\\d+(?:[.,]\\d+)?)\\s*мм\\b\', norm(value))\n    if not match:return None\n    return tuple(Decimal(v.replace(\',\',\'.\')) for v in match.groups())\n\ndef reconcile(results, text):\n    marker=re.search(r\'### DOCUMENT: [^\\n]*00_Позиции_ГПБ\\.txt\\r?\\n\',text)\n    if not marker:return results,[]\n    try:\n        source,_=json.JSONDecoder().raw_decode(text[marker.end():].lstrip())\n    except ValueError:return results,[]\n    rows=source.get(\'positions\') if isinstance(source,dict) else None\n    if not isinstance(rows,list) or not rows:return results,[]\n    if any(not isinstance(row,dict) for row in rows):return results,[]\n    lots={str(row.get(\'lot_id\')) for row in rows}\n    ids=[str(row.get(\'source_unit_id\') or \'\') for row in rows]\n    if len(lots)!=1 or \'None\' in lots or len(set(ids))!=len(ids) or not all(ids):\n        return results,[]\n    lookup={}\n    for i,row in enumerate(rows,1):\n        key=profile_key(row.get(\'name\'))\n        if key is None or key in lookup:return results,[]\n        lookup[key]=(i,row)\n    copied=[r.model_copy(deep=True) for r in results]\n    groups={}\n    for result in copied:\n        for pos in result.positions:\n            keys={profile_key(v) for v in (pos.product_name.value,pos.product_name.raw_quote)}-{None}\n            if len(keys)!=1 or next(iter(keys)) not in lookup:\n                # Never discard an unmatched line or accidentally collide identities.\n                return results,[]\n            index,row=lookup[next(iter(keys))]\n            if pos.lot_number not in (None,\'\',\'1\',str(row[\'lot_id\'])):return results,[]\n            groups.setdefault(index,[]).append(pos)\n    if set(groups)!=set(range(1,len(rows)+1)):return results,[]\n    audit=[]\n    labels={\'width_mm\':\'ширин\',\'length_mm\':\'длин\',\'thickness_mm\':\'толщин\',\'diameter_mm\':\'диаметр\'}\n    for index,variants in groups.items():\n        row=rows[index-1]\n        for pos in variants:\n            pos.lot_number=\'1\'  # Internal single-lot ordinal; source lot_id retained in audit.\n            pos.position_number=index\n            pos.product_name.value=row[\'name\']\n            pos.product_type.value=\'профиль\'\n        dimensions=[]\n        for field,label in labels.items():\n            entries=[getattr(pos,field) for pos in variants]\n            explicit=[]\n            for item in entries:\n                quote=item.raw_quote or \'\'\n                if re.search(label,quote,re.I):\n                    if norm(quote) not in norm(text):\n                        raise ValueError(\'GPB_DIMENSION_QUOTE_NOT_IN_SOURCE: \'+field)\n                    explicit.append(item)\n                elif item.value is not None or quote:\n                    # Only a bare two-dimensional designation is ambiguous here.\n                    q=norm(quote)\n                    if not re.fullmatch(r\'(?:профиль\\s+алюминиевый\\s+)?\\d+(?:[.,]\\d+)?\\s*[хx×]\\s*\\d+(?:[.,]\\d+)?\\s*мм\',q):\n                        raise ValueError(\'GPB_DIMENSION_EVIDENCE_UNRESOLVED: \'+field)\n            if not explicit:continue\n            signatures={(norm(e.value),norm(e.raw_quote)) for e in explicit}\n            if len(signatures)!=1:\n                raise ValueError(\'GPB_EXPLICIT_DIMENSION_CONFLICT: \'+field)\n            chosen=explicit[0].model_copy(deep=True)\n            if re.search(r\'не\\s+(?:более|менее)|[<>≤≥]\',chosen.raw_quote or \'\',re.I):\n                chosen.value=None\n            for pos in variants:setattr(pos,field,chosen.model_copy(deep=True))\n            dimensions.append(field)\n        # Source quantity is a check, not a license to sum or invent kilograms.\n        for pos in variants:\n            if pos.quantity.value is not None and row.get(\'quantity\') is not None:\n                try:equal=Decimal(str(pos.quantity.value).replace(\',\',\'.\'))==Decimal(str(row[\'quantity\']).replace(\',\',\'.\'))\n                except Exception:equal=False\n                if not equal:raise ValueError(\'GPB_SOURCE_QUANTITY_CONFLICT\')\n            if pos.unit.value is not None and row.get(\'okei_name\'):\n                if norm(pos.unit.value).rstrip(\'.\')!=norm(row[\'okei_name\']).rstrip(\'.\'):\n                    raise ValueError(\'GPB_SOURCE_UNIT_CONFLICT\')\n        audit.append({\'position\':index,\'source_unit_id\':row[\'source_unit_id\'],\n                      \'source_lot_id\':row[\'lot_id\'],\'variants\':len(variants),\n                      \'explicit_dimension_fields\':dimensions})\n    return copied,audit\n'), ('app/scoring/selection_policy.py', 'd3c93183beb36f3300cf8a68ecd5b6693c173d06d82f03e26255ce78c0edce1c', '"""Shared STD procurement criteria. No database, network or credentials."""\nimport math\nimport re\n\nVERSION = \'std-selection-20261019-pieces200\'\nMIN_WEIGHT_KG = 500.0\nMIN_PIECES = 200\nOKPD2_PREFIXES = (\'24.42.11\', \'24.42.22\', \'24.42.23\', \'24.42.24\', \'24.42.25\', \'24.42.26\')\n# Product words are a fallback only for sites without a structured classifier.\nFALLBACK_QUERIES = (\'алюминий\', \'алюминиевый прокат\', \'цветной металлопрокат\',\n    \'алюминиевая лента\', \'алюминиевый лист\', \'алюминиевый профиль\',\n    \'алюминиевая труба\', \'алюминиевый пруток\', \'алюминиевая шина\',\n    \'алюминиевая плита\', \'алюминиевая полоса\', \'алюминиевая катанка\', \'алюминиевая фольга\')\nPRODUCT = re.compile(r\'\\b(?:лист\\w*|лент\\w*|плит\\w*|рулон\\w*|фольг\\w*|штрипс\\w*|труб\\w*|прут\\w*|профил\\w*|шин\\w*|полос\\w*|катанк\\w*|уголок\\w*|круг\\w*|заготов\\w*|слит\\w*|чушк\\w*|sheet|strip|plate|pipe|profile|bar|round|busbar|flat_bar|wire_rod|foil)\\b\',re.I)\nNON_TARGET = re.compile(r\'\\b(?:стал\\w*|сталь|медн\\w*|латун\\w*|бронз\\w*|кабел\\w*|провод\\w*|сип[-\\s]?\\d|стремянк\\w*|лестниц\\w*|посуда)\\b\', re.I)\nALUMINIUM = re.compile(r\'алюмини|alumin\', re.I)\n# Only distinctive Russian aluminium series; unknown labels alone do not prove metal.\nALLOY = re.compile(r\'(?<!\\w)(?:АД\\s*\\d+|АМ[ГЦ]\\s*\\d*|Д(?:1|16|19)|В95|ВД1|АК(?:4|6)|А[0567])(?:[А-Яа-я]\\d*)*(?!\\w)\', re.I)\n\n\ndef number(value):\n    if value is None or isinstance(value, bool): return None\n    try:\n        x = float(str(value).replace(\'\\xa0\',\'\').replace(\' \',\'\').replace(\',\',\'.\'))\n        return x if math.isfinite(x) and x >= 0 else None\n    except (TypeError,ValueError): return None\n\n\ndef mass_kg(position):\n    mass = number(position.get(\'mass_kg\'))\n    if mass is None: mass = number(position.get(\'quantity_kg\'))\n    if mass is not None: return mass\n    qty = number(position.get(\'quantity\'))\n    unit = str(position.get(\'unit\') or \'\').strip().lower().rstrip(\'.\')\n    if qty is None: return None\n    if unit in (\'кг\',\'kg\',\'килограмм\',\'килограммы\',\'килограммов\',\'166\'): return qty\n    if unit in (\'т\',\'тн\',\'тонна\',\'тонны\',\'тонн\',\'t\',\'ton\',\'tonne\',\'168\'): return qty * 1000\n    return None\n\n\ndef material_status(position):\n    name = str(position.get(\'name_product\') or position.get(\'product_name\') or position.get(\'name\') or \'\')\n    kind = str(position.get(\'product_type\') or \'\')\n    alloy = str(position.get(\'alloy\') or position.get(\'alloy_normalized\') or \'\')\n    text = \' \'.join((name, kind, alloy))\n    if NON_TARGET.search(text): return False\n    if not PRODUCT.search(name + \' \' + kind): return False if kind else None\n    from app.marketplace_discovery.subject_classifier import classify_tender_subject\n    if not classify_tender_subject(\'Поставка \' + name).allowed: return False\n    if ALUMINIUM.search(text) or ALLOY.search(text): return True\n    from app.scoring.alloy_normalizer import is_known_alloy\n    return True if alloy and is_known_alloy(alloy) else None\n\n\n\ndef piece_count(position):\n    unit = str(position.get(\'unit\') or position.get(\'okei_name\') or \'\').strip().casefold().rstrip(\'.\')\n    if unit not in (\'шт\', \'штука\', \'штуки\', \'штук\', \'pcs\', \'pc\', \'piece\', \'pieces\', \'796\'):\n        return None\n    qty = number(position.get(\'quantity\'))\n    return qty if qty is not None and qty.is_integer() else None\n\n\ndef volume_status(position):\n    """Known mass takes precedence; only absent mass permits the piece fallback."""\n    mass = mass_kg(position)\n    if mass is not None:\n        return mass >= MIN_WEIGHT_KG\n    if any(position.get(k) not in (None, \'\') for k in (\'mass_kg\', \'quantity_kg\')):\n        return None\n    count = piece_count(position)\n    return count >= MIN_PIECES if count is not None else None\n\ndef qualifies(position):\n    return material_status(position) is True and volume_status(position) is True\n\n\ndef processing_required(value):\n    if isinstance(value, bool): return value\n    s = str(value or \'\').strip().lower().replace(\'ё\',\'е\')\n    if s in (\'\', \'нет\', \'false\', \'no\', \'0\', \'null\', \'none\', \'не указано\', \'не требуется\', \'отсутствует\', \'без покрытия\', \'без обработки\'): return False\n    if re.match(r\'^(?:не требуется|не предусмотрен|отсутствует|без покрытия|без обработки)\\b\', s): return False\n    return bool(re.search(r\'\\b(?:да|true|yes|требуется|резк\\w*|окраск\\w*|покрыти\\w*|анодирован\\w*|гибк\\w*|фрезер\\w*|сверлен\\w*)\\b\',s))\n\n\ndef price_priority(amount, currency=\'RUB\'):\n    value = number(amount)\n    if str(currency or \'RUB\').upper() not in (\'RUB\',\'RUR\',\'РУБ\',\'РУБ.\',\'₽\'): return \'currency_review\'\n    if value is None: return \'price_unknown\'\n    return \'high\' if value >= 1_000_000 else (\'normal\' if value >= 500_000 else \'low\')\n\n\ndef policy():\n    return dict(version=VERSION, min_position_mass_kg=MIN_WEIGHT_KG, min_position_pieces_without_mass=MIN_PIECES, mass_precedence=True, sum_positions=False,\n        okpd2_prefixes=OKPD2_PREFIXES, geography=\'РФ и СНГ\', all_customers=True,\n        all_industries=True, all_aluminium_alloys=True, laws=[\'44-FZ\',\'223-FZ\',\'commercial\'],\n        price_priority_rub=1_000_000, price_secondary_rub=500_000,\n        unknown_price_allowed=True, advance_restricted=False, security_restricted=False,\n        kontur_enabled=False, tender_pro_min_request_interval_seconds=1.1)\n'), ('app/scoring/multiposition.py', '35e41a943d4727965210d7a0a49b78611720fc2bb0c25e7b7f5a6ca9dcb6c29f', '"""\nАнализ многопозиционных тендеров.\nОпределяет по каждой позиции: можем ли мы её поставить.\nЕсли не можем поставить все — проверяем допустимость частичной поставки.\n"""\nfrom dataclasses import dataclass\nfrom typing import Optional\nimport re\nimport math\nfrom app.models.database import TenderStatus\n\nfrom app.scoring.alloy_normalizer import is_known_alloy, normalize_alloy_string\nfrom app.scoring.selection_policy import material_status, mass_kg as position_mass, MIN_WEIGHT_KG, volume_status, piece_count, MIN_PIECES\nfrom app.core.logging import get_logger\n\nlogger = get_logger(__name__)\n\n# Типы продукции которые мы поставляем\nOUR_PRODUCT_TYPES = {\n    "лента", "лента тисненная", "лист", "плита", "рулон",\n    "фольга", "штрипсы", "лента алюминиевая", "лист алюминиевый",\n    "плита алюминиевая", "рулон алюминиевый",\n    "труба", "трубы", "пруток", "прутки", "профиль", "профили",\n}\n\n\n@dataclass\nclass PositionAnalysis:\n    position_number: int\n    name_product: str\n    alloy: Optional[str]\n    product_type: Optional[str]\n    mass_kg: Optional[float]\n    thickness_mm: Optional[float]\n    width_mm: Optional[float]\n    can_supply: Optional[bool]\n    reason: str\n\n\n@dataclass\nclass MultiPositionResult:\n    total_positions: int\n    can_supply_all: bool\n    can_supply_count: int\n    cannot_supply_count: int\n    partial_delivery_possible: bool\n    positions: list[PositionAnalysis]\n    summary: str\n    unknown_count: int = 0\n\n\ndef analyze_positions(positions: list[dict], partial_delivery_allowed: bool = None) -> MultiPositionResult:\n    """\n    Анализирует каждую позицию многопозиционного тендера.\n\n    positions: список словарей с полями alloy, product_type, mass_kg и т.д.\n    partial_delivery_allowed: из документов тендера (None = не указано)\n    """\n    analyzed = []\n\n    for i, pos in enumerate(positions, 1):\n        alloy_raw = pos.get("alloy") or pos.get("alloy_normalized")\n        product_type = (pos.get("product_type") or "").lower().strip()\n        mass_kg = position_mass(pos)\n        material = material_status(pos)\n        product_ok = material is True\n\n        # Проверка сплава\n        alloy_ok = False\n        alloy_normalized = None\n        if alloy_raw:\n            alloy_normalized = normalize_alloy_string(alloy_raw)\n            alloy_ok = is_known_alloy(alloy_raw)\n\n        # Итоговое решение по позиции\n        if not product_type:\n            can_supply = None\n            reason = "Тип продукции не указан — требует уточнения"\n        elif material is False:\n            can_supply = False\n            reason = f"Тип \'{product_type}\' вне нашего ассортимента"\n        elif material is None:\n            can_supply = None\n            reason = "Не подтверждено, что позиция относится к алюминиевой продукции"\n        elif mass_kg is not None and mass_kg < MIN_WEIGHT_KG:\n            can_supply = False\n            reason = f"Объём {mass_kg} кг ниже минимальной партии (500 кг)"\n        elif mass_kg is None and volume_status(pos) is False:\n            can_supply = False\n            reason = f"Количество {piece_count(pos):g} шт. ниже минимальной партии ({MIN_PIECES} шт. при неизвестной массе)"\n        elif not alloy_raw or volume_status(pos) is not True or not any(pos.get(k) for k in ("thickness_mm", "width_mm", "diameter_mm")):\n            can_supply = None\n            reason = "Тип продукции в ассортименте; требуется уточнить сплав, объём (массу либо количество в штуках) и/или размеры"\n        else:\n            can_supply = True\n            reason = "Алюминиевая продукция соответствует условиям отбора"\n            if mass_kg is None:\n                reason += f"; {piece_count(pos):g} шт., масса не указана"\n            if alloy_normalized:\n                reason += f" ({alloy_normalized})"\n\n        analyzed.append(PositionAnalysis(\n            position_number=i,\n            name_product=pos.get("name_product") or pos.get("product_name", f"Позиция {i}"),\n            alloy=alloy_normalized or alloy_raw,\n            product_type=product_type,\n            mass_kg=mass_kg,\n            thickness_mm=pos.get("thickness_mm"),\n            width_mm=pos.get("width_mm"),\n            can_supply=can_supply,\n            reason=reason,\n        ))\n\n    can_count = sum(1 for p in analyzed if p.can_supply)\n    cannot_count = sum(p.can_supply is False for p in analyzed)\n    unknown_count = sum(p.can_supply is None for p in analyzed)\n    can_all = bool(analyzed) and can_count == len(analyzed)\n\n    # Частичная поставка возможна если:\n    # 1. Явно разрешена в документах, или не запрещена (None)\n    # 2. Хотя бы одну позицию можем поставить\n    partial_ok = (partial_delivery_allowed is True) and can_count > 0\n\n    if unknown_count:\n        summary = f"Требуют уточнения: {unknown_count}; соответствуют: {can_count}; не соответствуют: {cannot_count}"\n    elif can_all:\n        summary = f"✅ Все {len(analyzed)} позиции в нашем ассортименте"\n    elif can_count == 0:\n        summary = f"❌ Ни одну из {len(analyzed)} позиций не можем поставить"\n    else:\n        summary = (\n            f"⚠️ {can_count} из {len(analyzed)} позиций — наши. "\n            f"{\'Частичная поставка допустима.\' if partial_ok else \'Частичная поставка НЕ допускается.\'}"\n        )\n\n    return MultiPositionResult(\n        total_positions=len(analyzed),\n        can_supply_all=can_all,\n        can_supply_count=can_count,\n        cannot_supply_count=cannot_count,\n        partial_delivery_possible=partial_ok,\n        positions=analyzed,\n        summary=summary,\n        unknown_count=unknown_count,\n    )\n\n\ndef position_status(scoring, mp):\n    if any(s.name == "hard_stop_word" for s in scoring.signals):\n        return TenderStatus.NOT_SUITABLE\n    if mp is None or mp.unknown_count:\n        return TenderStatus.MANUAL_REVIEW\n    if mp.can_supply_count == 0:\n        return TenderStatus.NOT_SUITABLE\n    if not mp.can_supply_all:\n        return TenderStatus.NEEDS_CLARIFICATION if mp.partial_delivery_possible else TenderStatus.MANUAL_REVIEW\n    return scoring.suggested_status\n'), ('app/workers/tasks_scoring.py', 'c41a711502f8830556917b2b053e23d7c81cce1b1bc2d515ef5872454bfacc5d', '"""Tender-level LLM extraction, multi-position analysis and persistence for v6."""\nimport asyncio\nimport httpx\nimport anthropic\nfrom datetime import datetime\n\nfrom sqlalchemy import delete, select, update\nfrom sqlalchemy.orm import joinedload\n\nfrom app.core.config import settings\nfrom app.core.logging import get_logger\nfrom app.db.session import SyncSessionLocal\nfrom app.llm.extraction import extract_tender_positions\nfrom app.models.database import Document, Decision, ExtractedFact, Lot, ProcessingStatus, Tender, TenderItem, TenderStatus\nfrom app.scoring.alloy_normalizer import is_known_alloy\nfrom app.scoring.multiposition import analyze_positions, position_status\nfrom app.scoring.rules import score_tender\nfrom app.scoring.selection_policy import processing_required, mass_kg as position_mass, price_priority, VERSION, volume_status\nfrom app.sources.eis_freshness import gate_saved_tender\nfrom app.workers.completed_analysis import has_completed_analysis, cached_result\nfrom app.workers.celery_app import celery_app\nfrom app.workers.execution_guard import exclusive_task\n\nlogger = get_logger(__name__)\nMODEL_VERSION = "scoring-v6.2-20260915"\n\n\ndef _num(val):\n    try:\n        return float(str(val).replace(",", ".")) if val not in (None, "") else None\n    except (ValueError, TypeError):\n        return None\n\n\ndef _bool(val):\n    if isinstance(val, bool):\n        return val\n    if val is None:\n        return None\n    s = str(val).strip().lower()\n    if s in {"true", "да", "yes", "1", "разрешена", "допускается"}: return True\n    if s in {"false", "нет", "no", "0", "запрещена", "не допускается"}: return False\n    return None\n\n\n@celery_app.task(name="app.workers.tasks_scoring.analyze_tender", bind=True, max_retries=2)\n@exclusive_task(\'analysis\', \'tender_id\')\ndef analyze_tender(self, tender_id: str, document_text: str = "", document_ids: list[str] | None = None, *, force_reanalysis: bool = False, suppress_notifications: bool = False):\n    try:\n        with SyncSessionLocal() as session:\n            tender = session.get(Tender, tender_id)\n            if not tender:\n                return {"status": "failed", "reason": "tender_not_found"}\n            if not force_reanalysis and has_completed_analysis(session, tender):\n                logger.info("tender_analysis_reused", tender_id=tender_id)\n                return cached_result(tender_id)\n            blocked = gate_saved_tender(session, tender_id)\n            if blocked:\n                logger.info(\'eis_freshness_skipped\', **blocked)\n                return blocked\n            # Old queued OCR messages must not analyze an incomplete or replaced snapshot.\n            if document_ids is not None:\n                current_ids = {str(value) for value in session.execute(\n                    select(Document.id).where(Document.tender_id == tender_id)\n                ).scalars().all()}\n                if (not document_ids or set(document_ids) != current_ids\n                        or tender.processing_status in (ProcessingStatus.FAILED, ProcessingStatus.DOCUMENTS_PENDING)):\n                    logger.warning("analysis_document_snapshot_unavailable", tender_id=tender_id)\n                    return {"status": "skipped", "reason": "document_snapshot_unavailable", "tender_id": tender_id}\n            session.execute(update(Tender).where(Tender.id == tender_id).values(processing_status=ProcessingStatus.ANALYZING))\n            metadata_parts = [\n                tender.title,\n                tender.description,\n                tender.delivery_place,\n            ]\n\n            source_key = tender.source\n            raw_payload = tender.raw_payload or {}\n            source_positions = raw_payload.get("positions", [])\n\n            if source_positions:\n                position_lines = ["ПОЗИЦИИ ТЕНДЕРА:"]\n\n                for idx, position in enumerate(source_positions, 1):\n                    if not isinstance(position, dict):\n                        continue\n\n                    name = position.get("name") or ""\n                    quantity = position.get("quantity")\n                    unit = position.get("unit") or ""\n\n                    line = f"{idx}. {name}"\n\n                    if quantity not in (None, ""):\n                        line += f" | количество: {quantity} {unit}".rstrip()\n\n                    position_lines.append(line)\n\n                if len(position_lines) > 1:\n                    metadata_parts.append(\n                        "\\n".join(position_lines)\n                    )\n\n            metadata_text = "\\n\\n".join(\n                str(value)\n                for value in metadata_parts\n                if value not in (None, "")\n            )\n\n            session.commit()\n\n        combined_text = (\n            metadata_text\n            + "\\n\\n"\n            + (document_text or "")\n        ).strip()\n        if not combined_text:\n            raise ValueError("Нет текста для анализа")\n\n        extracted = asyncio.run(extract_tender_positions(combined_text))\n        positions = []\n        for pos in extracted.positions:\n            positions.append({\n                "name_product": pos.product_name.value,\n                "product_type": pos.product_type.value or pos.product_name.value,\n                "alloy": pos.alloy.value,\n                "mass_kg": position_mass({"mass_kg":pos.mass_kg.value,"quantity":pos.quantity.value,"unit":pos.unit.value}),\n                "quantity_kg": _num(pos.mass_kg.value),\n                "quantity": pos.quantity.value,\n                "unit": pos.unit.value,\n                "thickness_mm": _num(pos.thickness_mm.value),\n                "width_mm": _num(pos.width_mm.value),\n                "diameter_mm": _num(pos.diameter_mm.value),\n            })\n\n        partial = _bool(extracted.partial_delivery_allowed.value)\n        if (raw_payload.get("b2b_public") or {}).get("all_positions_required"):\n            partial = False\n        if (raw_payload.get(\'metal_it\') or {}).get(\'all_positions_required\'):\n            partial = False\n        if (raw_payload.get(\'gpb\') or {}).get(\'all_positions_required\'):\n            partial = False\n        mp = analyze_positions(positions, partial_delivery_allowed=partial) if positions else None\n        any_alloy = any(x.get("alloy") and is_known_alloy(x["alloy"]) for x in positions)\n        any_dims = any(x.get("thickness_mm") or x.get("width_mm") for x in positions)\n        any_mass = any(volume_status(x) is True for x in positions)\n        standards = [p.standard.value for p in extracted.positions if p.standard.value]\n        drawings = any(_bool(p.has_drawings.value) for p in extracted.positions)\n        processing = any(processing_required(p.coating.value) or processing_required(p.machining.value) for p in extracted.positions)\n\n        scoring = score_tender(\n            text=combined_text,\n            has_alloy_match=any_alloy,\n            has_dimensions=any_dims,\n            has_volume=any_mass,\n            has_standard_ref=bool(standards),\n            has_drawings=drawings,\n            has_processing_services=processing,\n        )\n\n        status = position_status(scoring, mp)\n        if raw_payload.get(\'multi_pipeline\') and partial is None and status != TenderStatus.NOT_SUITABLE:\n            status = TenderStatus.MANUAL_REVIEW\n            scoring.critical_unknowns.append(\'Условия подачи заявки по отдельным позициям не подтверждены\')\n        if source_key == \'gpb\' and (raw_payload.get(\'gpb\') or {}).get(\'participation_unknown\') and status != TenderStatus.NOT_SUITABLE:\n            status = TenderStatus.MANUAL_REVIEW\n            scoring.critical_unknowns.append(\'ГПБ: условия подачи заявки по отдельным позициям требуют проверки\')\n        public = raw_payload.get(\'b2b_public\') or {}\n        if source_key == \'b2b_center\' and public.get(\'documents_restricted\') and status != TenderStatus.NOT_SUITABLE:\n            status = TenderStatus.MANUAL_REVIEW\n            scoring.critical_unknowns.append(\'Документация организатора требует входа; анализ основан на публичных позициях\')\n        with SyncSessionLocal() as session:\n            blocked = gate_saved_tender(session, tender_id)\n            if blocked: return blocked\n\n        _save(tender_id, extracted, mp, scoring, status, document_ids or [])\n\n        if (\n            not suppress_notifications\n            and settings.notifications_enabled\n            and status in (\n                TenderStatus.CAN_APPLY,\n                TenderStatus.NEEDS_CLARIFICATION,\n                TenderStatus.MANUAL_REVIEW,\n            )\n        ):\n            payload = {\n                "total_score": scoring.total_score,\n                "category": scoring.category.value,\n                "suggested_status": status.value,\n                "summary": mp.summary if mp else "Позиции не распознаны",\n            }\n\n            from app.workers.tasks_notify import (\n                send_telegram_notification,\n                send_bitrix_notification,\n            )\n\n            send_telegram_notification.delay(\n                tender_id,\n                payload,\n            )\n\n            send_bitrix_notification.delay(\n                tender_id,\n                payload,\n            )\n\n        return {"status": "analyzed", "tender_id": tender_id, "score": scoring.total_score, "decision": status.value, "positions": len(positions)}\n    except Exception as exc:\n        logger.exception("tender_analysis_failed", tender_id=tender_id, error_type=type(exc).__name__, error=str(exc))\n        with SyncSessionLocal() as session:\n            previous = session.get(Tender, tender_id)\n            if not has_completed_analysis(session, previous):\n                session.execute(update(Tender).where(Tender.id == tender_id).values(processing_status=ProcessingStatus.FAILED))\n            elif previous.analysis_done:\n                previous.processing_status = ProcessingStatus.ANALYZED\n            session.commit()\n        status_code = getattr(exc, "status_code", getattr(getattr(exc, "response", None), "status_code", None))\n        transient = isinstance(exc, (TimeoutError, httpx.TransportError, anthropic.APIConnectionError)) or status_code in {408, 429, 500, 502, 503, 504}\n        if transient and self.request.retries < self.max_retries:\n            raise self.retry(exc=exc, countdown=60 * (2 ** self.request.retries))\n        # No synthetic successful analysis, automatic approval or notification.\n        raise\n\n\ndef _save(tender_id, extracted, mp, scoring, status, document_ids):\n    with SyncSessionLocal() as session:\n        tender = session.execute(select(Tender).where(Tender.id == tender_id).options(joinedload(Tender.lots).joinedload(Lot.items))).unique().scalar_one()\n        # Replace generated analysis snapshot on re-analysis.\n        for lot in list(tender.lots):\n            session.delete(lot)\n        session.execute(delete(Decision).where(Decision.tender_id == tender_id))\n        session.flush()\n\n        lots: dict[str, Lot] = {}\n        analyses = mp.positions if mp else []\n        for idx, pos in enumerate(extracted.positions, 1):\n            lot_no = pos.lot_number or "1"\n            if lot_no not in lots:\n                lot = Lot(tender_id=tender_id, lot_number=str(lot_no), title=f"Лот {lot_no}", currency=tender.currency, delivery_place=tender.delivery_place)\n                session.add(lot); session.flush(); lots[lot_no] = lot\n            pa = analyses[idx-1] if idx-1 < len(analyses) else None\n            item = TenderItem(\n                lot_id=lots[lot_no].id,\n                position_number=pos.position_number or idx,\n                name=pos.product_name.value,\n                product_type=pos.product_type.value or pos.product_name.value,\n                alloy=pos.alloy.value,\n                temper=pos.temper.value,\n                thickness_mm=_num(pos.thickness_mm.value), width_mm=_num(pos.width_mm.value),\n                length_mm=_num(pos.length_mm.value), diameter_mm=_num(pos.diameter_mm.value),\n                quantity=_num(pos.quantity.value), mass_kg=position_mass({"mass_kg":pos.mass_kg.value,"quantity":pos.quantity.value,"unit":pos.unit.value}), unit=pos.unit.value,\n                standard=pos.standard.value, coating_required=processing_required(pos.coating.value), coating_type=pos.coating.value,\n                machining_required=processing_required(pos.machining.value), has_drawings=bool(_bool(pos.has_drawings.value)),\n                delivery_place=pos.delivery_place.value, delivery_term=pos.delivery_term.value, payment_terms=pos.payment_terms.value,\n                can_supply=pa.can_supply if pa else None, supply_reason=pa.reason if pa else None,\n            )\n            session.add(item)\n\n        reasons = [s.reason for s in scoring.signals]\n        if mp:\n            reasons.append(mp.summary)\n            reasons.extend(f\'Позиция {p.position_number}: {p.reason}\' for p in mp.positions if p.can_supply is not True)\n        session.add(Decision(\n            tender_id=tender_id, score=scoring.total_score, status=status,\n            reasons=reasons, risks=scoring.critical_unknowns, model_version=MODEL_VERSION,\n        ))\n\n        # Save explainability facts against first available document.\n        first_doc = document_ids[0] if document_ids else None\n        if first_doc:\n            for pi, pos in enumerate(extracted.positions, 1):\n                for field_name, field in pos.model_dump().items():\n                    if isinstance(field, dict) and (field.get("value") is not None or field.get("raw_quote")):\n                        session.add(ExtractedFact(\n                            document_id=first_doc, field_name=f"position_{pi}.{field_name}",\n                            raw_value=str(field.get("value")), normalized_value=str(field.get("value")) if field.get("value") is not None else None,\n                            confidence=field.get("confidence") or 0.0, quote=field.get("raw_quote"),\n                        ))\n\n        tender.raw_payload = {**(tender.raw_payload or {}), \'selection_policy_version\': VERSION,\n            \'price_priority\': price_priority(tender.amount,tender.currency)}\n        tender.analysis_done = True\n        tender.processing_status = ProcessingStatus.ANALYZED\n        tender.analysis_version = settings.analysis_version\n        tender.score = scoring.total_score\n        tender.status = status\n        tender.updated_at = datetime.utcnow()\n        session.commit()\n        from app.marketplace_discovery.review_store import remove_candidate\n        remove_candidate(tender.source,tender.external_id)\n\n\n# Compatibility wrapper for legacy task names.\n@celery_app.task(name="app.workers.tasks_scoring.extract_fields_and_score")\ndef extract_fields_and_score(tender_external_id: str, document_text: str, tender_db_id: str = None, document_db_id: str = None):\n    if not tender_db_id:\n        return {"status": "deprecated", "reason": "tender_db_id is required in v6"}\n    return analyze_tender.run(tender_db_id, document_text, [document_db_id] if document_db_id else [])\n'), ('app/reports/dashboard_eligibility.py', 'e31c2b80a3800ea724e1f937f57de114e2f661203d1d8ee9e8bd838fadc27574', '"""Dashboard admission uses the same mass criterion as scoring."""\nfrom dataclasses import dataclass\nfrom app.scoring.selection_policy import qualifies, mass_kg, piece_count\n\n@dataclass\nclass DashboardEligibility:\n    eligible: bool\n    reason: str\n    qualifying_position: dict | None = None\n\ndef evaluate_dashboard_tender(tender):\n    if not tender.get(\'analysis_done\') or tender.get(\'status\') not in (\'can_apply\',):\n        return DashboardEligibility(False, \'analysis_not_approved\')\n    for pos in tender.get(\'positions\') or []:\n        if pos.get(\'can_supply\') is True and qualifies(pos):\n            mass = mass_kg(pos)\n            reason = f\'position_weight_ok:{mass:g}kg\' if mass is not None else f\'position_pieces_ok:{piece_count(pos):g}pcs\'\n            return DashboardEligibility(True, reason, pos)\n    return DashboardEligibility(False, \'no_single_position_above_threshold\')\n')]
TESTS = 'from app.llm.gpb_position_reconcile import reconcile\nfrom app.llm.extraction import TenderMultiExtractionResult, _merge_extractions\nimport json\n\ndef f(v=None,q=None):return {\'value\':v,\'raw_quote\':q,\'confidence\':0.9}\nrows=[{\'source_unit_id\':str(i),\'lot_id\':\'2361818\',\'name\':f\'Профиль алюминиевый {w}х{h}ММ ООО "АГРИСОВГАЗ" Россия\',\'quantity\':\'4000\',\'okei_name\':\'ШТ\'} for i,(w,h) in enumerate([(120,90),(40,200),(60,200),(60,90),(80,200)],1)]\nresults=[]\nquotes=[]\nfor variant in range(3):\n    positions=[]\n    for i,row in enumerate(rows,1):\n        size=row[\'name\'].split()[2]; w,h=size[:-2].split(\'х\')\n        p={\'position_number\':i,\'lot_number\':\'2361818\' if variant==1 else None,\'product_name\':f(\'Профиль алюминиевый\' if variant==0 else row[\'name\'],row[\'name\']),\'product_type\':f(\'профиль\' if variant!=2 else \'алюминиевый профиль\',row[\'name\'])}\n        if variant<2:\n            p.update(quantity=f(\'4000\',\'4000\'),width_mm=f(w if variant==0 else h,size))\n            if variant==1:p[\'unit\']=f(\'шт\',\'ШТ\')\n        else:\n            for field,label,n in [(\'width_mm\',\'Ширина\',w),(\'length_mm\',\'Длина\',h),(\'thickness_mm\',\'Толщина\',\'10\')]:\n                q=f\'{label} не более {int(n)+1} мм и не менее {int(n)-1} мм\';quotes.append(q);p[field]=f(None,q)\n        positions.append(p)\n    results.append(TenderMultiExtractionResult.model_validate({\'positions\':positions}))\ntext=\'### DOCUMENT: 00_Позиции_ГПБ.txt\\n\'+json.dumps({\'positions\':rows},ensure_ascii=False)+\'\\n### DOCUMENT: spec.docx\\n\'+\'\\n\'.join(quotes)\nfixed,audit=reconcile(results,text);merged=_merge_extractions(fixed)\nassert len(merged.positions)==5 and len(audit)==5\nfor p in merged.positions:\n    assert p.quantity.value==\'4000\' and p.unit.value==\'шт\' and p.mass_kg.value is None\n    assert p.width_mm.value is None and \'не более\' in p.width_mm.raw_quote\nassert results[1].positions[0].width_mm.value==\'90\', \'original snapshot mutated\'\nbad=[r.model_copy(deep=True) for r in results];bad[0].positions[0].quantity.value=\'8000\'\ntry:reconcile(bad,text)\nexcept ValueError as exc:assert \'QUANTITY_CONFLICT\' in str(exc)\nelse:raise AssertionError(\'quantity conflict ignored\')\n# Unknown lines and different lots are never silently mapped or removed.\nbad=[r.model_copy(deep=True) for r in results];bad[1].positions[0].lot_number=\'other\'\nassert reconcile(bad,text)[1]==[]\nbad=[r.model_copy(deep=True) for r in results];bad[2].positions[0].width_mm.raw_quote=\'Ширина не более 999 мм\'\ntry:reconcile(bad,text)\nexcept ValueError as exc:assert \'QUOTE_NOT_IN_SOURCE\' in str(exc)\nelse:raise AssertionError(\'unsupported quote accepted\')\nprint(\'GPB_RECONCILE_TESTS_OK: five rows, no quantity addition, ranges retained, originals retained, conflict guards\')\n\nfrom app.scoring.selection_policy import qualifies,volume_status,mass_kg\nfrom app.scoring.multiposition import analyze_positions\nfrom app.reports.dashboard_eligibility import evaluate_dashboard_tender\nbase={\'name_product\':\'Профиль алюминиевый АД31\',\'product_type\':\'профиль\',\'alloy\':\'АД31\',\'width_mm\':120,\'quantity\':200,\'unit\':\'шт\'}\nassert qualifies(base)\nassert not qualifies(dict(base,quantity=199))\nassert qualifies(dict(base,quantity=4000))\nassert not qualifies(dict(base,quantity=4000,mass_kg=499))\nassert qualifies(dict(base,quantity=1,mass_kg=500))\nassert not qualifies(dict(base,unit=\'м\'))\nassert not qualifies(dict(base,unit=None))\nassert not qualifies(dict(base,quantity=200.5))\nassert volume_status(dict(base,mass_kg=\'неизвестно\')) is None\nassert not qualifies(dict(base,name_product=\'Стулья\',product_type=\'стул\'))\nassert mass_kg(base) is None\nassert analyze_positions([base],False).can_supply_all\nassert analyze_positions([dict(base,quantity=100),dict(base,quantity=100)],True).can_supply_count==0\nassert analyze_positions([dict(base,alloy=None)],False).unknown_count==1\nresult=evaluate_dashboard_tender({\'analysis_done\':True,\'status\':\'can_apply\',\'positions\':[dict(base,can_supply=True)]})\nassert result.eligible and result.reason==\'position_pieces_ok:200pcs\'\nassert not evaluate_dashboard_tender({\'analysis_done\':False,\'status\':\'can_apply\',\'positions\':[dict(base,can_supply=True)]}).eligible\nprint(\'PIECES_THRESHOLD_TESTS_OK: 199/200/4000 pcs, mass precedence, units, no summation, aluminium gate, dashboard\')\n'
REPLAY = 'import json,hashlib\nfrom pathlib import Path\nfrom sqlalchemy import select,update\nfrom app.core.config import settings\nfrom app.db.session import SyncSessionLocal\nfrom app.models.database import Tender,Document,ProcessingStatus\nfrom app.llm import extraction as e\nfrom app.llm.gpb_position_reconcile import reconcile\nfrom app.sources.eis_freshness import gate_saved_tender\nfrom app.workers.completed_analysis import has_completed_analysis\nTID=\'2742c177-b7d7-4e4e-996a-15ab3ea07ca6\'\npath=Path(settings.storage_path)/\'extraction_snapshots\'/\'eda4624b43cc2b3f-0ifgop4d\'/\'responses.json\'\nsnapshot=json.loads(path.read_text())\nwith SyncSessionLocal() as db:\n    tender=db.get(Tender,TID)\n    if not tender or tender.source!=\'gpb\' or str(tender.external_id)!=\'2077557\':raise SystemExit(\'IDENTITY_MISMATCH\')\n    docs=db.execute(select(Document).where(Document.tender_id==TID).order_by(Document.created_at,Document.id)).scalars().all()\n    if len(docs)!=4 or any(not d.extracted_text or str(getattr(d.ocr_status,\'value\',d.ocr_status)) not in (\'done\',\'not_required\') for d in docs):raise SystemExit(\'DOCUMENTS_NOT_READY\')\n    metadata=[tender.title,tender.description,tender.delivery_place]\n    lines=[\'ПОЗИЦИИ ТЕНДЕРА:\']\n    for idx,pos in enumerate((tender.raw_payload or {}).get(\'positions\',[]),1):\n        if not isinstance(pos,dict):continue\n        line=f"{idx}. {pos.get(\'name\') or \'\'}"\n        if pos.get(\'quantity\') not in (None,\'\'):line+=f" | количество: {pos.get(\'quantity\')} {pos.get(\'unit\') or \'\'}".rstrip()\n        lines.append(line)\n    if len(lines)>1:metadata.append(\'\\n\'.join(lines))\n    meta=\'\\n\\n\'.join(str(x) for x in metadata if x not in (None,\'\'))\n    document_text=\'\'.join(f\'\\n\\n### DOCUMENT: {d.filename}\\n{d.extracted_text}\' for d in docs)\n    text=(meta+\'\\n\\n\'+document_text).strip()\n    if hashlib.sha256(text.encode()).hexdigest()!=snapshot[\'input_sha256\']:\n        raise SystemExit(\'INPUT_SNAPSHOT_MISMATCH; no analysis submitted\')\n    chunks=e._document_chunks(text,limit=8000)\n    saved=snapshot[\'responses\']\n    if len(saved)!=len(chunks):raise SystemExit(\'INCOMPLETE_SNAPSHOT\')\n    results=[]\n    for i,(chunk,row) in enumerate(zip(chunks,saved)):\n        if row[\'chunk_index\']!=i or row[\'chunk_sha256\']!=hashlib.sha256(chunk.encode()).hexdigest():raise SystemExit(\'CHUNK_MISMATCH\')\n        results.append(e._normalize_extraction(e.TenderMultiExtractionResult.model_validate(row[\'result\']),text))\n    reconciled,audit=reconcile(results,text)\n    merged=e._merge_extractions(reconciled)\n    if len(merged.positions)!=5 or len(audit)!=5:raise SystemExit(\'UNEXPECTED_REPLAY_RESULT\')\n    print(\'OFFLINE_REPLAY_OK: positions=5; no LLM calls\',flush=True)\n    print(json.dumps({\'mapping\':audit,\'positions\':[{\'number\':p.position_number,\'name\':p.product_name.value,\'quantity\':p.quantity.value,\'unit\':p.unit.value,\'mass_kg\':p.mass_kg.value} for p in merged.positions]},ensure_ascii=False),flush=True)\n    from app.llm.reliable_extraction import digest, VERSION\n    fingerprint=digest(json.dumps({\n        \'version\':VERSION,\'input\':digest(text),\n        \'route\':e.llm_router._resolve_route(e.TaskType.EXTRACT_FIELDS),\n        \'schema\':e.TenderMultiExtractionResult.model_json_schema(),\n        \'prompt\':e.MULTI_EXTRACTION_SYSTEM_PROMPT,\n        \'code\':digest(Path(e.__file__).read_text()),\n    },sort_keys=True,ensure_ascii=False))\n    cache=Path(settings.storage_path)/\'extraction_snapshots\'/\'_validated_cache\'/fingerprint\n    for i,chunk in enumerate(chunks):\n        cached=cache/(str(i)+\'-\'+digest(chunk)+\'.json\')\n        result=e.TenderMultiExtractionResult.model_validate(json.loads(cached.read_text()))\n        original=e.TenderMultiExtractionResult.model_validate(saved[i][\'result\'])\n        if result.model_dump()!=original.model_dump():raise SystemExit(\'CACHE_SNAPSHOT_MISMATCH\')\n    print(\'ALL_VALIDATED_CHECKPOINTS_PRESENT\',flush=True)\n    if not RESUME:\n        print(\'READ_ONLY_REPLAY: no DB writes or task submissions\');raise SystemExit(0)\n    if has_completed_analysis(db,tender):print(\'ALREADY_ANALYZED\');raise SystemExit(0)\n    blocked=gate_saved_tender(db,TID)\n    if blocked:print(\'BLOCKED:\',blocked);raise SystemExit(0)\n    if tender.processing_status!=ProcessingStatus.FAILED:print(\'NOT_FAILED; no duplicate task\');raise SystemExit(0)\n    from app.workers.celery_app import celery_app\n    from app.workers.tasks_scoring import analyze_tender\n    client=celery_app.backend.client\n    key=\'recovery:gpb-evidence-20261019:\'+TID\n    if not client.set(key,\'reserved\',nx=True,ex=86400):print(\'ALREADY_RESERVED\');raise SystemExit(0)\n    # Re-arm only this validated document snapshot, not the source\'s whole backlog.\n    tender.processing_status=ProcessingStatus.DOCUMENTS_READY\n    ids=[str(d.id) for d in docs]\n    db.commit()\n    task=analyze_tender.delay(TID,document_text,ids,suppress_notifications=True)\n    client.set(key,task.id,xx=True,ex=86400)\n    print(\'GPB_SCORING_QUEUED:\',task.id,flush=True)\n'
import argparse,hashlib,os,shutil,subprocess,tempfile
from pathlib import Path

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--resume-gpb',action='store_true')
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    root=Path.cwd();changes={}
    for rel,before,after in FILES:
        p=root/rel
        old=p.read_bytes() if p.exists() else None
        if old==after.encode():continue
        digest=hashlib.sha256(old).hexdigest() if old is not None else None
        if digest!=before:raise SystemExit('VERSION_CONFLICT: '+rel+'; no changes')
        compile(after,rel,'exec');changes[p]=after
    print('COMPATIBLE; FILES:',len(changes),flush=True)
    if args.check:return
    backup=Path(tempfile.mkdtemp(prefix='gpb-reconcile-backup-',dir=root.parent))
    for p,text in changes.items():
        if p.exists():
            dest=backup/p.relative_to(root);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
    print('BACKUP:',backup,flush=True)
    for p,text in changes.items():
        fd,tmp=tempfile.mkstemp(dir=p.parent)
        with os.fdopen(fd,'w') as f:f.write(text)
        os.chmod(tmp,p.stat().st_mode & 0o777 if p.exists() else 0o644);os.replace(tmp,p)
    subprocess.run(['docker','compose','build','app','celery_worker','celery_discovery'],check=True)
    subprocess.run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,check=True)
    subprocess.run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input='RESUME=False\n'+REPLAY,text=True,check=True)
    ids=subprocess.check_output(['docker','compose','ps','-q','celery_worker','celery_discovery'],text=True).split()
    if ids:
        print('Waiting for warm shutdown of running tasks.',flush=True)
        subprocess.run(['docker','kill','--signal=SIGTERM',*ids],check=True)
        subprocess.run(['docker','wait',*ids],check=True)
    subprocess.run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery'],check=True)
    print('GPB_POSITION_RECONCILE_INSTALLED',flush=True)
    if args.resume_gpb:
        subprocess.run(['docker','compose','exec','-T','celery_discovery','python','-'],input='RESUME=True\n'+REPLAY,text=True,check=True)
    print('Schedules and completed analyses retained. No mass requeue, downloads or notifications.',flush=True)
if __name__=='__main__':main()
